function createVoiceRacingGame(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas || canvas.width !== 500 || canvas.height !== 500) return;
  const ctx = canvas.getContext('2d');

  // UI elements
  const btnStart = document.createElement('button');
  btnStart.textContent = 'Start Race';
  btnStart.style.position = 'absolute';
  btnStart.style.top = '520px';
  btnStart.style.left = '10px';
  document.body.appendChild(btnStart);
  const btnMute = document.createElement('button');
  btnMute.textContent = 'Mute';
  btnMute.style.position = 'absolute';
  btnMute.style.top = '520px';
  btnMute.style.left = '120px';
  document.body.appendChild(btnMute);
  const meterCanvas = document.createElement('canvas');
  meterCanvas.width = 200;
  meterCanvas.height = 20;
  meterCanvas.style.position = 'absolute';
  meterCanvas.style.top = '520px';
  meterCanvas.style.left = '240px';
  document.body.appendChild(meterCanvas);
  const meterCtx = meterCanvas.getContext('2d');
  const bestLapDiv = document.createElement('div');
  bestLapDiv.style.position = 'absolute';
  bestLapDiv.style.top = '560px';
  bestLapDiv.style.left = '10px';
  document.body.appendChild(bestLapDiv);
  const statusDiv = document.createElement('div');
  statusDiv.style.position = 'absolute';
  statusDiv.style.top = '560px';
  statusDiv.style.left = '200px';
  document.body.appendChild(statusDiv);

  // Audio setup
  let audioCtx, analyser, source, gainNode;
  let microphoneStream;
  let volValue = 0;
  let muted = false;
  try {
    navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
      microphoneStream = stream;
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      source = audioCtx.createMediaStreamSource(stream);
      gainNode = audioCtx.createGain();
      analyser = audioCtx.createAnalyser();
      analyser.fftSize = 512;
      analyser.smoothingTimeConstant = 0.8;
      source.connect(gainNode).connect(analyser);
    }).catch(e => {
      console.log('Microphone access denied', e);
    });
  } catch (e) {
    console.log('Web Audio not supported', e);
  }

  btnMute.onclick = () => {
    muted = !muted;
    if (gainNode) gainNode.gain.value = muted ? 0 : 1;
    btnMute.textContent = muted ? 'Unmute' : 'Mute';
  };

  // Game variables
  const car = { x: 250, y: 350, angle: -Math.PI / 2, radius: 10, color: 'red' };
  const track = { centerX: 250, centerY: 250, radius: 150, width: 80 };
  const obstacles = [
    { x: 250, y: 150, r: 15 },
    { x: 150, y: 250, r: 20 }
  ];
  let speed = 0;
  const maxSpeed = 5;
  let lastTime = null;
  let raceStarted = false;
  let startAngle = car.angle;
  let lapStartTime = 0;
  let lapCount = 0;
  let bestLap = parseFloat(localStorage.getItem('voiceRace-best')) || null;

  btnStart.onclick = () => {
    raceStarted = true;
    startAngle = car.angle;
    lapStartTime = performance.now();
    lapCount = 0;
    requestAnimationFrame(loop);
  };

  function drawTrack() {
    ctx.strokeStyle = '#555';
    ctx.lineWidth = track.width;
    ctx.beginPath();
    ctx.arc(track.centerX, track.centerY, track.radius, 0, Math.PI * 2);
    ctx.stroke();
    ctx.fillStyle = '#777';
    ctx.beginPath();
    ctx.arc(track.centerX, track.centerY, track.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawCar() {
    ctx.fillStyle = car.color;
    ctx.beginPath();
    ctx.arc(car.x, car.y, car.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawObstacles() {
    ctx.fillStyle = 'black';
    obstacles.forEach(o => {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function detectCollision() {
    // Check track boundaries
    const dx = car.x - track.centerX;
    const dy = car.y - track.centerY;
    const d = Math.sqrt(dx * dx + dy * dy);
    const inner = track.radius - track.width / 2;
    const outer = track.radius + track.width / 2;
    if (d < inner || d > outer) return true;
    // Check obstacles
    for (const o of obstacles) {
      const dist = Math.hypot(car.x - o.x, car.y - o.y);
      if (dist < car.radius + o.r) return true;
    }
    return false;
  }

  function updateCar(delta) {
    speed = volValue * maxSpeed;
    if (!raceStarted) speed = 0;
    car.angle += speed * delta / 1000;
    const rad = car.angle;
    car.x = track.centerX + track.radius * Math.cos(rad);
    car.y = track.centerY + track.radius * Math.sin(rad);
    if (detectCollision() && !muted) {
      // Crash physics
      const bounce = Math.PI + (Math.random() * Math.PI / 4 - Math.PI / 8);
      car.angle += bounce;
      speed *= 0.3;
    }
  }

  function updateLap() {
    if ((car.angle - startAngle) % (Math.PI * 2) < -Math.PI) {
      lapCount++;
      const lapTime = performance.now() - lapStartTime;
      lapStartTime = performance.now();
      let bestText = 'Best Lap: N/A';
      if (!bestLap || lapTime < bestLap) {
        bestLap = lapTime;
        localStorage.setItem('voiceRace-best', bestText = `Best Lap: ${(bestLap / 1000).toFixed(2)}s`);
      } else {
        bestText = `Best Lap: ${(bestLap / 1000).toFixed(2)}s`;
      }
      bestLapDiv.textContent = `${bestText} | Current Lap: ${(lapTime / 1000).toFixed(2)}s`;
      if (lapCount >= 3) {
        raceStarted = false;
        statusDiv.textContent = 'Race Finished! 🎉';
      }
    }
  }

  function drawMeter() {
    meterCtx.clearRect(0, 0, meterCanvas.width, meterCanvas.height);
    meterCtx.fillStyle = '#00f';
    const barWidth = meterCanvas.width * volValue;
    meterCtx.fillRect(0, 0, barWidth, meterCanvas.height);
  }

  function loop(time) {
    if (!lastTime) lastTime = time;
    const delta = time - lastTime;
    lastTime = time;
    const bufferLength = analyser ? analyser.frequencyBinCount : 0;
    const dataArray = new Uint8Array(bufferLength);
    if (analyser) analyser.getByteTimeDomainData(dataArray);
    let sum = 0;
    for (let i = 0; i < bufferLength; i++) sum += Math.abs(dataArray[i] - 128);
    volValue = sum / bufferLength / 128;
    if (volValue > 1) volValue = 1;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawTrack();
    drawObstacles();
    updateCar(delta);
    drawCar();
    updateLap();
    drawMeter();
    if (raceStarted) requestAnimationFrame(loop);
  }
}
